                    GET
                
                <set-variable name="result" value="@{
    var crypto = ((IResponse)context.Variables["cryptoResponse"]).Body.As();
    var equity = ((IResponse)context.Variables["equityResponse"]).Body.As();
    var exchange = ((IResponse)context.Variables["exchangeRateResponse"]).Body.As();
    var audRate = exchange["rates"]?["AUD"] ?? null;
    return new JObject {
        ["cryptoPricesAUD"] = crypto,
        ["equityPricesUSD"] = equity,
        ["usdToAudRate"] = audRate
    }.ToString();
}" />
                
                
                
                    
                    
